// app/api/forgot-password/route.ts

import { NextResponse } from 'next/server'
import { connectDB } from '../../../lib/db'
import { User } from '../../../models/user'
import crypto from 'crypto'

export async function POST(req: Request) {
  const { email } = await req.json()
  await connectDB()

  const allowedDomains = process.env.ALLOWED_DOMAINS?.split(',') || ['gmail.com', 'yahoo.com']
  const domain = email.split('@')[1]

  if (!allowedDomains.includes(domain)) {
    return NextResponse.json({ message: `Hanya email dari ${allowedDomains.join(', ')} yang diperbolehkan` }, { status: 400 })
  }

  const user = await User.findOne({ email })
  if (!user) {
    return NextResponse.json({ message: 'Email tidak ditemukan' }, { status: 404 })
  }

  // Generate token dan expiry (1 jam)
  const token = crypto.randomBytes(32).toString('hex')
  const tokenExpires = new Date(Date.now() + 1000 * 60 * 60) // 1 jam

  // Simpan ke user
  user.resetToken = token
  user.resetTokenExpires = tokenExpires
  await user.save()

  const resetLink = `${process.env.NEXT_PUBLIC_BASE_URL}/reset-password?token=${token}`

  // TODO: Kirim email menggunakan Resend atau Nodemailer
  console.log(`Link reset password: ${resetLink}`)

  return NextResponse.json({ success: true })
}
